using System.Text.Json;
using System.Text.RegularExpressions;
using BotZone.Contracts;
namespace BotZone.Infrastructure.Services;
public sealed partial class CommandService
{
 static string Slug(JsonElement p,string field="slug"){var value=p.Text(field);Access.Ensure(Regex.IsMatch(value,"^[a-z0-9]+(?:-[a-z0-9]+)*$")&&value.Length<=120,"VALIDATION_ERROR","Slug cần chữ thường, số và dấu gạch ngang.",400);return value;}
 async Task<object?> Catalogue(Actor a,string command,JsonElement p){switch(command){
  case "save_category":{Access.Require(a,"owner");var id=p.MaybeId("id")??Guid.NewGuid();var code=p.Text("code").Trim().ToUpperInvariant();Access.Ensure(code.Length is >=2 and <=40&&p.Text("nameVi").Length is >=1 and <=100&&p.Text("nameEn").Length is >=1 and <=100,"VALIDATION_ERROR","Thông tin nhóm không hợp lệ.",400);return await sql.One("INSERT INTO categories(id,code,slug,name_vi,name_en,active) VALUES($1,$2,$3,$4,$5,$6) ON CONFLICT(id) DO UPDATE SET code=excluded.code,slug=excluded.slug,name_vi=excluded.name_vi,name_en=excluded.name_en,active=excluded.active RETURNING id",id,code,Slug(p),p.Text("nameVi"),p.Text("nameEn"),p.Bool("active",true));}
  case "create_product":{Access.Require(a,"owner");var source=p.Text("sourceUrl");Access.Ensure(Uri.TryCreate(source,UriKind.Absolute,out var url)&&url.Scheme=="https","VALIDATION_ERROR","Cần URL nguồn HTTPS.",400);var poster=p.Text("poster","/media/phone-front.svg");Access.Ensure(Regex.IsMatch(poster,"^/media/[a-z0-9_-]+\\.svg$"),"VALIDATION_ERROR","Chọn poster từ thư viện minh họa local.",400);var id=Guid.NewGuid();await sql.Exec("INSERT INTO products(id,category_id,slug,model_code,business_status,generation,source_url,poster) VALUES($1,$2,$3,$4,'draft',$5,$6,$7)",id,p.Id("categoryId"),Slug(p),p.Text("modelCode").Trim(),p.Text("generation",""),source,poster);foreach(var locale in new[]{"vi","en"}){var name=p.Text(locale=="vi"?"nameVi":"nameEn");Access.Ensure(name.Length is >=1 and <=200,"VALIDATION_ERROR","Cần tên sản phẩm cả VI và EN.",400);await sql.Exec("INSERT INTO product_translations(product_id,locale,name,description,seo_title,content_status) VALUES($1,$2,$3,'',$3,'draft')",id,locale,name);}return new{id,businessStatus="draft"};}
  case "update_product_status":{Access.Require(a,"owner");var status=p.Text("businessStatus");Access.Ensure(new[]{"draft","active","discontinued","archived"}.Contains(status),"VALIDATION_ERROR","Trạng thái không hợp lệ.",400);return await sql.One("UPDATE products SET business_status=$2 WHERE id=$1 RETURNING id,business_status",p.Id("productId"),status);}
  case "create_variant":{Access.Require(a,"owner");var product=p.Id("productId");var mode=p.Text("trackingMode");Access.Ensure(mode is "serialized" or "quantity","VALIDATION_ERROR","Chế độ theo dõi không hợp lệ.",400);var options=p.Field("options");Access.Ensure(options.ValueKind==JsonValueKind.Object&&options.EnumerateObject().Count()<=20,"VALIDATION_ERROR","Thuộc tính SKU không hợp lệ.",400);var canonical=new SortedDictionary<string,string>(StringComparer.Ordinal);foreach(var opt in options.EnumerateObject()){Access.Ensure(opt.Name.Length is >=1 and <=40&&opt.Value.ValueKind==JsonValueKind.String&&opt.Value.GetString()!.Length<=100,"VALIDATION_ERROR","Thuộc tính cần chuỗi tối đa 100 ký tự.",400);if(!string.IsNullOrWhiteSpace(opt.Value.GetString()))canonical[opt.Name]=opt.Value.GetString()!.Trim();}var signature=Values.Json(canonical);var sku=p.Text("sku").Trim().ToUpperInvariant();Access.Ensure(sku.Length is >=2 and <=80&&Regex.IsMatch(sku,"^[A-Z0-9_-]+$"),"VALIDATION_ERROR","SKU cần chữ, số, gạch ngang hoặc gạch dưới.",400);int months=p.Int("standardWarrantyMonths");Access.Ensure(months is >=0 and <=60,"VALIDATION_ERROR","Thời hạn bảo hành không hợp lệ.",400);long? fee=p.TryGetProperty("careFeeVnd",out var cv)&&cv.ValueKind==JsonValueKind.String&&cv.GetString()!.Length>0?p.Money("careFeeVnd"):null;Access.Ensure(fee is null||months>0,"VALIDATION_ERROR","Care cần thời hạn bảo hành tiêu chuẩn.",400);return await sql.One("INSERT INTO product_variants(product_id,sku,option_signature,options,price_vnd,tracking_mode,standard_warranty_months,care_fee_vnd,active) VALUES($1,$2,$3,$3::jsonb,$4,$5,$6,$7,$8) RETURNING id,sku",product,sku,signature,p.Money("priceVnd"),mode,months,fee,p.Bool("active",true));}
  case "set_compatibility":{Access.Require(a,"owner");var accessory=p.Id("accessoryProductId");var ids=p.Array("targetProductIds").Select(v=>Guid.Parse(v.GetString()!)).Distinct().ToArray();Access.Ensure(ids.Length<=100&&!ids.Contains(accessory),"VALIDATION_ERROR","Tương thích không hợp lệ.",400);await sql.One("SELECT id FROM products WHERE id=$1",accessory);await sql.Exec("DELETE FROM product_compatibilities WHERE accessory_product_id=$1",accessory);foreach(var id in ids)await sql.Exec("INSERT INTO product_compatibilities(accessory_product_id,target_product_id) VALUES($1,$2)",accessory,id);return new{saved=true,count=ids.Length};}
  default:return null;
 }}
 static void Permission(Actor a,string command,JsonElement input){var roles=command switch{
  "save_cart" or "place_order" or "save_profile" or "save_address" or "sync_wishlist" or "request_return" or "request_trade_in" or "decide_trade_in" or "request_warranty"=>new[]{"customer"},
  "save_landing" or "publish_landing" or "restore_landing" or "update_translation"=>["content_staff"],
  "preview_landing" or "revoke_landing_preview"=>["owner","content_staff"],
  "handoff" or "receive_goods" or "request_stock_adjustment" or "inspect_failed_shipment" or "receive_return" or "inspect_return" or "receive_trade_in" or "inspect_trade_in"=>["warehouse_staff"],
  "create_purchase" or "save_supplier"=>["owner","warehouse_staff"],
  "confirm_order" or "create_invoice_draft" or "shipment_event" or "quote_trade_in"=>["owner","order_staff"],
  "start_payment" or "record_payment" or "cancel_order"=>["customer","owner","order_staff"],
  "approve_return_intake" or "resolve_return"=>["order_staff"],
  "return_trade_in"=>["warehouse_staff"],
  "trade_in_shipment"=>["order_staff","warehouse_staff"],
  "finalize_trade_in"=>["owner","order_staff"],
  "resolve_trade_in_exception"=>["owner"],
  "read_notification"=>["customer","owner","order_staff","warehouse_staff","content_staff"],
  "process_warranty"=>input.Text("action") switch{"inspect" or "repair" or "repaired" or "unrepairable"=>["warehouse_staff"],"replace"=>["owner","warehouse_staff"],"receive" or "close"=>["order_staff"],_=>["owner"]},
  "update_variant" or "update_staff" or "save_settings" or "update_settings" or "create_promotion" or "save_category" or "create_product" or "create_variant" or "update_product_status" or "set_compatibility" or "approve_purchase" or "approve_stock_adjustment" or "approve_return" or "execute_refund" or "approve_trade_in_quote" or "finalize_failed_delivery" or "close_failed_shipment"=>["owner"],
  _=>throw new BusinessException("UNKNOWN_COMMAND","Lệnh chưa được hỗ trợ.",400)};Access.Require(a,roles);}
 static void ValidateSetting(string key,JsonElement value){if(key!="commerce")return;Access.Ensure(value.ValueKind==JsonValueKind.Object,"VALIDATION_ERROR","Chính sách phải có các trường cấu hình.",400);var allowed=new[]{"shippingVnd","freeShippingVnd","pointsPerVnd","pointValueVnd","maxPointsPercent","returnDays"};Access.Ensure(value.EnumerateObject().All(p=>allowed.Contains(p.Name)),"VALIDATION_ERROR","Trường chính sách không được hỗ trợ.",400);foreach(var field in new[]{"shippingVnd","freeShippingVnd"})Access.Ensure(value.Money(field)<=1000000000,"VALIDATION_ERROR","Phí hoặc ngưỡng giao vượt giới hạn.",400);foreach(var field in new[]{"pointsPerVnd","pointValueVnd"})Access.Ensure(value.Money(field) is >=1 and <=1000000000,"VALIDATION_ERROR","Giá trị điểm phải dương và trong giới hạn.",400);Access.Ensure(value.Int("maxPointsPercent") is >=0 and <=100&&value.Int("returnDays") is >=1 and <=365,"VALIDATION_ERROR","Trần điểm hoặc cửa sổ trả không hợp lệ.",400);}
}
